#version 460
#extension GL_GOOGLE_include_directive : require
#include "pelican_sets.glsl"
#include "pelican_view.glsl"

layout(location = 0) in vec2 inUV;
layout(location = 0) out vec4 outColor;

PELICAN_DECLARE_INPUT_0(in_gbuffer_albedo);
PELICAN_DECLARE_INPUT_1(in_gbuffer_normal);

void main() {
    outColor = PELICAN_TEXTURE_2D_0(in_gbuffer_albedo, inUV) +
               0.0 * PELICAN_TEXTURE_2D_1(in_gbuffer_normal, inUV);
}

#version 460
#extension GL_GOOGLE_include_directive : require
#include "pelican_sets.glsl"
#include "pelican_view.glsl"

layout(location = 0) in vec2 inUV;
layout(location = 0) out vec4 outColor;

PELICAN_DECLARE_INPUT_0(in_gbuffer_albedo);

void main() {
    outColor = PELICAN_TEXTURE_2D_0(in_gbuffer_albedo, inUV);
}
